const S={token:localStorage.getItem('euas_token')||'',user:null,view:'home',ref:null,siteId:'',cache:{},fieldTab:'assigned',dashDate:new Date().toISOString().slice(0,10)};
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const NAV=[['home','⌂','Home'],['dashboard','▦','Dashboard'],['assets','◫','Assets'],['work','✓','Work'],['maintenance','↻','Maintenance'],['workforce','♙','Workforce'],['inventory','▤','Inventory'],['procurement','¤','Procurement'],['approvals','◉','Approvals'],['contracts','▥','Contracts'],['vendors','◇','Vendors'],['operations','⚡','Operations'],['telemetry','⌁','Telemetry'],['map','⌖','Map'],['field','▣','Field Service'],['dispatch','↯','Dispatch'],['inspections','☑','Inspections'],['hse','⚠','HSE'],['projects','◆','Projects'],['documents','▧','Documents'],['analytics','⌁','Analytics'],['automation','◎','Automation'],['administration','⚙','Administration']];
const TITLES={home:'Home',dashboard:'Executive Dashboard',assets:'Asset Management',work:'Work Management',maintenance:'Preventive Maintenance',workforce:'Workforce Planning',inventory:'Inventory Management',procurement:'Procurement',approvals:'Approval Center',contracts:'Contracts',vendors:'Vendors',operations:'Utilities Operations',telemetry:'Telemetry & Alarms',map:'GIS / Locations',field:'Field Service',dispatch:'Technician Dispatch',inspections:'Inspection Management',hse:'Safety & HSE',projects:'Projects',documents:'Document Management',analytics:'Analytics',automation:'Automation & Reports',administration:'Administration'};
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmtMoney=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(n||0));
const fmt=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:1}).format(Number(n||0));
const status=v=>`<span class="status ${esc(String(v).replaceAll(' ','-'))}">${esc(v)}</span>`;
const empty=msg=>`<div class="empty">${esc(msg)}</div>`;
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2300)}
async function api(path,opts={}){const headers={...(opts.headers||{}),...(S.token?{Authorization:`Bearer ${S.token}`}:{})};if(!(opts.body instanceof FormData)&&opts.body!==undefined)headers['Content-Type']='application/json';const r=await fetch(path,{...opts,headers});if(r.status===401){logout(false);throw new Error('Session expired')};const ct=r.headers.get('content-type')||'';const data=ct.includes('json')?await r.json():await r.text();if(!r.ok)throw new Error(data.detail||data||'Request failed');return data}
async function downloadProtected(path,filename){const r=await fetch(path,{headers:{Authorization:'Bearer '+S.token}});if(!r.ok){let msg='Download failed';try{const j=await r.json();msg=j.detail||msg}catch{}throw new Error(msg)}const b=await r.blob(),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=filename;a.click();URL.revokeObjectURL(u)}
async function openProtected(path){const r=await fetch(path,{headers:{Authorization:'Bearer '+S.token}});if(!r.ok)throw new Error('Unable to open report');const b=await r.blob(),u=URL.createObjectURL(b);window.open(u,'_blank');setTimeout(()=>URL.revokeObjectURL(u),60000)}
function roleIn(...roles){return roles.includes(S.user?.role)}
function canAsset(){return roleIn('admin','asset_manager','maintenance_manager','planner','supervisor')}
function canWork(){return roleIn('admin','maintenance_manager','planner','supervisor','technician')}
function canInv(){return roleIn('admin','maintenance_manager','planner','storekeeper','technician')}
function canProc(){return roleIn('admin','maintenance_manager','procurement')}
function canHSE(){return roleIn('admin','hse','maintenance_manager')}
function canProject(){return roleIn('admin','project_manager','maintenance_manager')}
function allowedWorkActions(w){const elevated=roleIn('admin','maintenance_manager','planner','supervisor'),supervisorRole=roleIn('admin','maintenance_manager','supervisor'),assignedTech=S.user?.role==='technician'&&Number(w.assigned_to)===Number(S.user.id);if(w.status==='Draft'&&elevated)return ['submit'];if(w.status==='Rejected'&&elevated)return ['resubmit'];if(w.status==='Submitted'&&supervisorRole)return ['approve'];if(w.status==='Approved'&&elevated)return ['assign'];if(w.status==='Assigned'&&(elevated||assignedTech))return ['start'];if(w.status==='In Progress'&&(elevated||assignedTech))return ['pause','complete'];if(w.status==='Completed'&&supervisorRole)return ['close'];return []}
function optionList(items,value='id',label='name',selected=null,blank='— Select —'){return `${blank!==null?`<option value="">${blank}</option>`:''}${items.map(x=>`<option value="${x[value]}" ${String(x[value])===String(selected)?'selected':''}>${esc(typeof label==='function'?label(x):x[label])}</option>`).join('')}`}
function field(label,name,type='text',value='',opts={}){const req=opts.required===false?'':'required';const full=opts.full?'full':'';if(type==='select')return `<label class="field ${full}">${esc(label)}<select name="${name}" ${req}>${opts.options||''}</select></label>`;if(type==='textarea')return `<label class="field ${full}">${esc(label)}<textarea name="${name}" ${req}>${esc(value)}</textarea></label>`;return `<label class="field ${full}">${esc(label)}<input type="${type}" name="${name}" value="${esc(value)}" ${req} ${opts.step?`step="${opts.step}"`:''}></label>`}
function openModal(title,html){$('#modal-title').textContent=title;$('#modal-body').innerHTML=html;$('#modal-layer').classList.remove('hidden')}
function closeModal(){$('#modal-layer').classList.add('hidden')}
$('#modal-close').onclick=closeModal;$('#modal-layer').onclick=e=>{if(e.target.id==='modal-layer')closeModal()};
function formModal(title,fields,onSubmit,submit='Save'){openModal(title,`<form id="dynamic-form" class="form-grid">${fields.join('')}<div class="form-actions"><button type="button" class="btn" id="cancel-form">Cancel</button><button class="btn primary">${esc(submit)}</button></div></form>`);$('#cancel-form').onclick=closeModal;$('#dynamic-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{await onSubmit(data,e.target);closeModal();toast('Saved successfully');await render()}catch(err){toast(err.message)}}}
function table(headers,rows){return `<div class="table-wrap"><table class="data-table"><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${headers.length}">${empty('No records found')}</td></tr>`}</tbody></table></div>`}
function kpi(label,value,icon,hint='',cls=''){return `<article class="kpi"><div class="kpi-top"><span class="kpi-label">${esc(label)}</span><span class="kpi-ico">${esc(icon)}</span></div><div class="kpi-value">${value}</div><div class="trend ${cls}">${hint}</div></article>`}
function barChart(items,labelKey,valueKey){const max=Math.max(1,...items.map(x=>Number(x[valueKey]||0)));return `<div class="chart-bars">${items.map(x=>`<div class="bar-row" title="${esc(x[labelKey])}: ${fmt(x[valueKey])}"><span>${esc(x[labelKey])}</span><div class="bar-track"><div class="bar-fill" style="width:${Math.max(4,Number(x[valueKey]||0)/max*100)}%"></div></div><b>${fmt(x[valueKey])}</b></div>`).join('')}</div>`}
function svgLine(items,valueKey,labelKey){const vals=items.map(x=>Number(x[valueKey]||0));const max=Math.max(1,...vals),w=520,h=140,p=15;const pts=vals.map((v,i)=>`${p+i*(w-2*p)/Math.max(vals.length-1,1)},${h-p-v/max*(h-2*p)}`).join(' ');return `<svg class="spark" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line class="grid" x1="${p}" y1="${h/2}" x2="${w-p}" y2="${h/2}"/><line class="grid" x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}"/><polyline points="${pts}"/>${vals.map((v,i)=>{const x=p+i*(w-2*p)/Math.max(vals.length-1,1),y=h-p-v/max*(h-2*p);return `<circle cx="${x}" cy="${y}" r="4"><title>${esc(items[i][labelKey])}: ${fmt(v)}</title></circle>`}).join('')}</svg>`}

async function login(username,password){const d=await api('/api/auth/login',{method:'POST',body:JSON.stringify({username,password})});S.token=d.token;S.user=d.user;localStorage.setItem('euas_token',S.token);await boot()}
async function restore(){if(!S.token)return;try{S.user=await api('/api/auth/me');await boot()}catch{}}
async function boot(){S.ref=await api('/api/reference');$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#user-name').textContent=S.user.full_name;$('#user-role').textContent=S.user.role_name||S.user.role;$('#profile-name').textContent=S.user.full_name.split(' ')[0];const initials=S.user.full_name.split(' ').map(x=>x[0]).slice(0,2).join('');$('#avatar').textContent=initials;$('#profile-initial').textContent=initials[0]||'U';$('#nav').innerHTML=NAV.map(n=>`<button class="nav-btn ${n[0]==='home'?'active':''}" data-view="${n[0]}"><span class="nav-ico">${n[1]}</span><span>${n[2]}</span></button>`).join('');$$('.nav-btn').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#site-selector').innerHTML='<option value="">All Sites</option>'+S.ref.sites.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');await refreshNotifications();await go('home')}
async function logout(call=true){if(call&&S.token){try{await api('/api/auth/logout',{method:'POST'})}catch{}}S.token='';S.user=null;localStorage.removeItem('euas_token');$('#app').classList.add('hidden');$('#login').classList.remove('hidden')}
$('#login-form').onsubmit=async e=>{e.preventDefault();$('#login-error').textContent='';const d=Object.fromEntries(new FormData(e.target));try{await login(d.username,d.password)}catch(err){$('#login-error').textContent=err.message}};$('#logout-btn').onclick=()=>logout();$('#profile-btn').onclick=()=>profileModal();$('#help-btn').onclick=()=>openModal('EUAS Help',`<p class="section-sub">Use the left navigation or Application Launchpad to open a module. Global Search finds connected assets, work orders, documents and inspections. Select a site to focus portfolio views. Field Service is role-aware and works best with the technician demo account.</p><div class="detail-grid"><div class="detail-box"><span>Management Demo</span><strong>omar / EUAS@2026</strong></div><div class="detail-box"><span>Technician Demo</span><strong>tech1 / Tech@2026</strong></div></div>`);
$('#site-selector').onchange=async e=>{S.siteId=e.target.value;await render()};$('#mobile-menu').onclick=()=>$('.sidebar').classList.toggle('open');
async function go(view){S.view=view;$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#page-title').textContent=TITLES[view]||view;$('#breadcrumb').textContent=`EUAS / ${TITLES[view]?.toUpperCase()||view.toUpperCase()}`;$('.sidebar').classList.remove('open');await render()}
async function render(){const fn={home:renderHome,dashboard:renderDashboard,assets:renderAssets,work:renderWork,maintenance:renderMaintenance,workforce:renderWorkforce,inventory:renderInventory,procurement:renderProcurement,approvals:renderApprovals,contracts:renderContracts,vendors:renderVendors,operations:renderOperations,telemetry:renderTelemetry,map:renderMap,field:renderField,dispatch:renderDispatch,inspections:renderInspections,hse:renderHSE,projects:renderProjects,documents:renderDocuments,analytics:renderAnalytics,automation:renderAutomation,administration:renderAdmin}[S.view];if(fn){$('#content').innerHTML='<div class="empty">Loading…</div>';try{await fn()}catch(e){$('#content').innerHTML=empty(e.message)}}}

let searchTimer;$('#global-search').oninput=e=>{clearTimeout(searchTimer);const q=e.target.value.trim();if(q.length<2){$('#search-results').classList.add('hidden');return}searchTimer=setTimeout(async()=>{try{const r=await api('/api/search?q='+encodeURIComponent(q));$('#search-results').innerHTML=r.length?r.map(x=>`<div class="search-item" data-module="${x.module}" data-id="${x.id}"><span class="code">${esc(x.code)}</span><div><strong>${esc(x.title)}</strong><small>${esc(x.subtitle)}</small></div></div>`).join(''):empty('No results');$('#search-results').classList.remove('hidden');$$('.search-item').forEach(i=>i.onclick=()=>{const m=i.dataset.module;$('#search-results').classList.add('hidden');$('#global-search').value='';go(m);setTimeout(()=>{if(m==='assets')assetDetail(Number(i.dataset.id));if(m==='work')workDetail(Number(i.dataset.id))},250)})}catch{}},250)};document.addEventListener('click',e=>{if(!e.target.closest('.search-wrap'))$('#search-results').classList.add('hidden')});
async function refreshNotifications(){if(!S.user)return;const n=await api('/api/notifications');S.cache.notifications=n;const unread=n.filter(x=>!x.is_read).length;$('#notif-count').textContent=unread;$('#notif-count').classList.toggle('hidden',!unread)}
$('#notification-btn').onclick=async()=>{await refreshNotifications();const n=S.cache.notifications||[],unread=n.filter(x=>!x.is_read).length;$('#drawer-body').innerHTML=`${unread?'<div class="drawer-tools"><button class="btn small" id="notif-read-all">Mark all read</button></div>':''}${n.length?n.map(x=>`<div class="notif-item ${x.is_read?'':'unread'}" data-id="${x.id}"><strong>${esc(x.title)}</strong><p>${esc(x.message)}</p><small>${esc(x.created_at)} · ${esc(x.severity)}</small></div>`).join(''):empty('No notifications')}`;$('#drawer').classList.remove('hidden');if($('#notif-read-all'))$('#notif-read-all').onclick=async()=>{await api('/api/notifications/read-all',{method:'POST'});await refreshNotifications();toast('Notifications marked as read');$('#drawer').classList.add('hidden')};$$('.notif-item').forEach((el,idx)=>el.onclick=async()=>{const item=n[idx];await api('/api/notifications/'+el.dataset.id+'/read',{method:'POST'});el.classList.remove('unread');await refreshNotifications();$('#drawer').classList.add('hidden');if(item.link_module&&TITLES[item.link_module])await go(item.link_module)})};$('#drawer-close').onclick=()=>$('#drawer').classList.add('hidden');
async function profileModal(){
  const sessions=await api('/api/auth/sessions');
  openModal('User Profile',`<div class="detail-grid"><div class="detail-box"><span>Name</span><strong>${esc(S.user.full_name)}</strong></div><div class="detail-box"><span>Username</span><strong>${esc(S.user.username)}</strong></div><div class="detail-box"><span>Role</span><strong>${esc(S.user.role_name||S.user.role)}</strong></div><div class="detail-box"><span>Email</span><strong>${esc(S.user.email||'—')}</strong></div><div class="detail-box"><span>Department</span><strong>${esc(S.user.department||'—')}</strong></div><div class="detail-box"><span>Active Sessions</span><strong>${sessions.length}</strong></div></div><div class="form-actions"><button class="btn" id="profile-edit">Edit Profile</button><button class="btn" id="profile-password">Change Password</button><button class="btn" id="profile-revoke">Revoke Other Sessions</button></div>`);
  $('#profile-edit').onclick=()=>editProfile();
  $('#profile-password').onclick=()=>changePassword();
  $('#profile-revoke').onclick=async()=>{try{const r=await api('/api/auth/sessions/revoke-others',{method:'POST'});toast(`${r.revoked} other session(s) revoked`);await profileModal()}catch(e){toast(e.message)}};
}
function refreshUserChrome(){
  $('#user-name').textContent=S.user.full_name;$('#user-role').textContent=S.user.role_name||S.user.role;$('#profile-name').textContent=S.user.full_name.split(' ')[0];
  const initials=S.user.full_name.split(' ').map(x=>x[0]).slice(0,2).join('');$('#avatar').textContent=initials;$('#profile-initial').textContent=initials[0]||'U';
}
function editProfile(){formModal('Edit Profile',[field('Full Name','full_name','text',S.user.full_name),field('Email','email','email',S.user.email||'',{required:false}),field('Department','department','text',S.user.department||'',{required:false}),field('Phone','phone','text',S.user.phone||'',{required:false})],async d=>{S.user=await api('/api/auth/profile',{method:'PATCH',body:JSON.stringify(d)});refreshUserChrome()})}
function changePassword(){formModal('Change Password',[field('Current Password','current_password','password'),field('New Password','new_password','password')],async d=>{await api('/api/auth/change-password',{method:'POST',body:JSON.stringify(d)});toast('Password changed; other sessions revoked')},'Update Password')}

async function renderHome(){const apps=await api('/api/launchpad');const d=await api('/api/dashboard'+(S.siteId?`?site_id=${S.siteId}`:''));$('#content').innerHTML=`<section class="suite-banner"><div><div class="eyebrow">ELSEWEDY UTILITIES APPLICATION SUITE</div><h1>One Platform. Every Asset. Every Operation.</h1><p>Unified asset, maintenance, utilities and field operations management.</p></div><div class="banner-stat"><div><strong>${d.kpis.total_assets}</strong><span>Assets</span></div><div><strong>${d.kpis.open_work_orders}</strong><span>Open Work</span></div><div><strong>${d.kpis.pm_compliance}%</strong><span>PM Compliance</span></div></div></section><div class="hero"><div><h1>Application Launchpad</h1><p>Connected enterprise applications for utilities operations.</p></div><div class="hero-actions"><button class="btn primary" id="home-new-wo">+ New Work Order</button><button class="btn" id="home-dashboard">Executive Dashboard</button></div></div><div class="launch-grid">${apps.map(a=>`<button class="launch-card" data-app="${a.code}"><span class="launch-icon">${a.icon}</span><strong>${esc(a.name)}</strong><span>${esc(a.description)}</span></button>`).join('')}</div>`;$$('.launch-card').forEach(x=>x.onclick=()=>go(x.dataset.app));$('#home-dashboard').onclick=()=>go('dashboard');$('#home-new-wo').onclick=()=>newWorkOrder()}

async function renderDashboard(){const qp=new URLSearchParams();if(S.siteId)qp.set('site_id',S.siteId);if(S.dashDate)qp.set('as_of',S.dashDate);const d=await api('/api/dashboard?'+qp);const k=d.kpis;const htotal=d.asset_health.reduce((a,b)=>a+b.count,0)||1;const good=(d.asset_health.find(x=>x.condition==='Good')?.count||0)/htotal*100;const fair=(d.asset_health.find(x=>['Fair','Warning'].includes(x.condition))?.count||0)/htotal*100;$('#content').innerHTML=`<div class="hero"><div><h1>Executive Dashboard</h1><p>${S.siteId?'Filtered by selected site':'Portfolio-wide utility performance overview'}.</p></div><div class="hero-actions"><input type="date" id="dash-date" value="${S.dashDate}" class="btn"><button class="btn" id="dash-refresh">Refresh</button></div></div><div class="kpi-grid">${kpi('Total Assets',k.total_assets,'AS','Enterprise asset base')}${kpi('Operating Assets',k.operating_assets,'OP',`${Math.round(k.operating_assets/Math.max(k.total_assets,1)*100)}% operational`,'good')}${kpi('Under Maintenance',k.assets_under_maintenance,'UM','Temporarily constrained')}${kpi('Critical Assets',k.critical_assets,'CR','Priority monitoring','warn')}${kpi('Open Work Orders',k.open_work_orders,'WO',`${k.overdue_work_orders} overdue`,k.overdue_work_orders?'warn':'good')}${kpi('Overdue Work',k.overdue_work_orders,'OD','Past target finish',k.overdue_work_orders?'warn':'good')}${kpi('Completed Work',k.completed_work_orders,'CP','Completed / closed')}${kpi('Emergency Work',k.emergency_work_orders,'EM','Immediate response')}${kpi('PM Compliance',k.pm_compliance+'%','PM','Target ≥ 95%',k.pm_compliance>=95?'good':'warn')}${kpi('MTBF',k.mtbf==null?'No failures':fmt(k.mtbf)+' h','BF','365-day reliability indicator')}${kpi('MTTR',k.mttr+' h','TR','Average repair time')}${kpi('Inventory Value',fmtMoney(k.inventory_value),'IV',`${k.low_stock_items} low stock`)}${kpi('Low Stock Items',k.low_stock_items,'LS','Reorder attention',k.low_stock_items?'warn':'good')}${kpi('Pending POs',k.pending_purchase_orders,'PO','Procurement pipeline')}${kpi('Active Technicians',k.active_technicians,'FS','Field resources')}${kpi('Safety Incidents',k.safety_incidents,'HS','Open HSE records',k.safety_incidents?'warn':'good')}${kpi('Open Outages',k.open_outages||0,'OT','Assets currently unavailable',(k.open_outages||0)?'bad':'good')}${kpi('Active Dispatches',k.active_dispatches||0,'DP','Technicians in dispatch lifecycle')}${kpi('Active Alarms',k.active_alarms||0,'AL',`${k.critical_alarms||0} critical`,(k.active_alarms||0)?'bad':'good')}${kpi('Utility Performance',k.utility_performance+'%','UP','Operating asset ratio',k.utility_performance>=95?'good':'warn')}${kpi('Asset Health Score',k.asset_health_score,'AH','Risk-weighted portfolio health',k.asset_health_score>=85?'good':k.asset_health_score>=70?'':'warn')}${kpi('90d Forecast Load',fmt(k.forecast_demand_hours_90d)+' h','FC',`Peak ${fmt(k.forecast_peak_utilization)}% utilization`,k.forecast_peak_utilization>100?'warn':'good')}${kpi('Parts-Blocked Work',k.parts_shortage_jobs_90d||0,'PB','90-day backlog with spare shortages',(k.parts_shortage_jobs_90d||0)?'warn':'good')}${kpi('Maintenance Cost',fmtMoney(k.maintenance_cost),'MC','Actual work cost')}</div><div class="panel-grid"><section class="panel"><div class="panel-head"><div><h3>Work Orders by Status</h3><p>Live workflow distribution</p></div></div><div class="panel-body">${barChart(d.wo_by_status,'status','count')}</div></section><section class="panel"><div class="panel-head"><div><h3>Asset Health Distribution</h3><p>Condition across the managed asset base</p></div></div><div class="panel-body"><div class="donut-wrap"><div class="donut" style="background:conic-gradient(var(--green) 0 ${good}%,var(--amber) ${good}% ${good+fair}%,var(--red) ${good+fair}% 100%)"><div class="donut-center"><strong>${Math.round(good)}%</strong><span>Good</span></div></div><div class="legend">${d.asset_health.map(x=>`<div><span class="dot ${x.condition==='Good'?'green':x.condition==='Fair'||x.condition==='Warning'?'amber':'red'}"></span>${esc(x.condition)} <b>${x.count}</b></div>`).join('')}</div></div></div></section></div><div class="panel-grid"><section class="panel"><div class="panel-head"><div><h3>Maintenance Cost by Asset</h3><p>Actual work-order cost</p></div></div><div class="panel-body">${svgLine(d.cost_by_asset,'cost','asset_no')}</div></section><section class="panel"><div class="panel-head"><div><h3>Recent Activity</h3><p>Audited enterprise actions</p></div></div><div class="panel-body"><div class="activity">${d.recent_activity.length?d.recent_activity.map(x=>`<div class="activity-item"><span class="activity-dot">${esc(x.action.slice(0,2))}</span><div><strong>${esc(x.full_name)} · ${esc(x.action)}</strong><p>${esc(x.module)} · ${esc(x.record_id)}</p></div><time>${esc(x.created_at.slice(5,16).replace('T',' '))}</time></div>`).join(''):empty('No activity')}</div></div></section></div>`;$('#dash-refresh').onclick=()=>renderDashboard();$('#dash-date').onchange=e=>{S.dashDate=e.target.value;renderDashboard()}}

