async function addPart(w){const items=await api('/api/inventory');formModal(`Issue Part — ${w.wo_no}`,[field('Inventory Item','item_id','select','',{options:optionList(items,'id',x=>`${x.item_no} — ${x.name} (${fmt(x.available_stock)} ${x.unit} available)`)}),field('Quantity','quantity','number','1',{step:'0.01'})],async d=>{d.item_id=Number(d.item_id);d.quantity=Number(d.quantity);await api(`/api/work-orders/${w.id}/materials`,{method:'POST',body:JSON.stringify(d)});await refreshNotifications()})}
