function fieldReading(w){if(!w.asset_id)return toast('This work order has no asset');formModal(`Asset Reading — ${w.asset_no}`,[field('Condition','condition','select','',{options:'<option>Good</option><option>Fair</option><option>Warning</option><option>Poor</option><option>Critical</option>'}),field('Meter Reading','meter_reading','number','',{required:false,step:'0.01'})],async d=>{await api(`/api/field/assets/${w.asset_id}/condition-meter`,{method:'POST',body:JSON.stringify({condition:d.condition,meter_reading:d.meter_reading?Number(d.meter_reading):null})})})}

async function renderMaintenance(){
  const [p,f]=await Promise.all([api('/api/maintenance-plans'),api('/api/planning/maintenance-forecast?horizon_days=90'+(S.siteId?`&site_id=${S.siteId}`:''))]);
  S.cache.pm=p;S.cache.forecast=f;
  const overdue=p.filter(x=>x.trigger_type==='Calendar'&&x.next_due&&x.next_due<new Date().toISOString().slice(0,10)).length;
  $('#content').innerHTML=`<div class="hero"><div><h1>Preventive Maintenance & Planning</h1><p>Calendar, runtime, meter, condition plans and forward workload/capacity forecasting.</p></div><div class="hero-actions">${canAsset()?'<button class="btn" id="pm-generate">Generate Due Work</button><button class="btn primary" id="pm-new">+ Maintenance Plan</button>':''}</div></div><div class="kpi-grid">${kpi('Active Plans',p.filter(x=>x.active).length,'PM','Maintenance strategies')}${kpi('Overdue PM',overdue,'OD',overdue?'Action required':'On schedule',overdue?'warn':'good')}${kpi('90d PM Jobs',f.summary.pm_jobs,'90','Forecasted preventive work')}${kpi('90d Demand',fmt(f.summary.demand_hours)+' h','DH',`Peak ${fmt(f.summary.peak_utilization_pct)}% capacity`,f.summary.peak_utilization_pct>100?'warn':'good')}${kpi('Technicians',f.technicians,'TC',`${fmt(f.weekly_capacity_hours)} h current-week capacity`)}${kpi('Parts Shortage',f.summary.parts_shortage_jobs||0,'PS','Backlog jobs blocked by planned spares',(f.summary.parts_shortage_jobs||0)?'warn':'good')}</div><section class="panel"><div class="panel-head"><div><h3>90-Day Maintenance Forecast</h3><p>Weekly PM + backlog demand against shift/absence-adjusted capacity and parts readiness.</p></div></div>${table(['Week','PM','Backlog','Demand','Capacity','Utilization','Parts','Craft Gaps','State'],f.weeks.map(w=>[w.week_start,w.pm_jobs,w.backlog_jobs,fmt(w.demand_hours)+' h',fmt(w.capacity_hours)+' h',fmt(w.utilization_pct)+'%',`${w.parts_ready_jobs} ready · ${w.parts_shortage_jobs} short · ${w.parts_unknown_jobs} unknown`,Object.entries(w.craft_states||{}).filter(([,v])=>v.shortage_hours>0).map(([k,v])=>`${esc(k)} ${fmt(v.shortage_hours)}h`).join(' · ')||'None',status(w.capacity_state)]))}</section><div class="card-grid" style="margin-top:14px">${p.map(x=>`<article class="entity-card"><div class="detail-head"><div><h3>${esc(x.name)}</h3><p>${esc(x.pm_no)} · ${esc(x.asset_no)} — ${esc(x.asset_name)}</p></div>${status(x.active?'Active':'Inactive')}</div><div class="meta-grid"><div class="meta"><span>Trigger</span><strong>${esc(x.trigger_type)}</strong></div><div class="meta"><span>Next Due</span><strong>${esc(x.next_due||'Meter based')}</strong></div><div class="meta"><span>Interval</span><strong>${x.interval_days?x.interval_days+' days':x.meter_interval?x.meter_interval+' units':'Condition'}</strong></div><div class="meta"><span>Priority</span><strong>${esc(x.priority)}</strong></div></div><p style="margin-top:12px">${esc(x.job_plan)}</p></article>`).join('')}</div>`;
  if(canAsset()){$('#pm-generate').onclick=async()=>{try{const d=await api('/api/maintenance-plans/generate',{method:'POST'});toast(`${d.count} work order(s) generated: ${d.generated.join(', ')||'none due'}`);await renderMaintenance();await refreshNotifications()}catch(e){toast(e.message)}};$('#pm-new').onclick=()=>newPM()}
}
async function newPM(){if(!S.cache.assets)S.cache.assets=await api('/api/assets');formModal('Create Maintenance Plan',[field('Plan Name','name','text','',{full:true}),field('Asset','asset_id','select','',{options:optionList(S.cache.assets,'id',x=>`${x.asset_no} — ${x.name}`)}),field('Trigger Type','trigger_type','select','',{options:'<option>Calendar</option><option>Meter</option><option>Runtime</option><option>Usage</option><option>Condition</option>'}),field('Interval Days','interval_days','number','90',{required:false}),field('Meter Interval','meter_interval','number','',{required:false,step:'0.01'}),field('Next Due','next_due','date','',{required:false}),field('Priority','priority','select','',{options:'<option>Low</option><option selected>Medium</option><option>High</option><option>Critical</option>'}),field('Job Plan','job_plan','textarea','',{full:true,required:false})],async d=>{d.asset_id=Number(d.asset_id);d.interval_days=d.interval_days?Number(d.interval_days):null;d.meter_interval=d.meter_interval?Number(d.meter_interval):null;await api('/api/maintenance-plans',{method:'POST',body:JSON.stringify(d)})})}

async function renderWorkforce(){
  const qs=S.siteId?`?site_id=${S.siteId}`:'';
  const [techs,cap,crafts,shifts,absences]=await Promise.all([api('/api/workforce/technicians'+qs),api('/api/workforce/capacity'+(S.siteId?`?site_id=${S.siteId}&weeks=8`:'?weeks=8')),api('/api/workforce/crafts'),api('/api/workforce/shifts'),api('/api/workforce/absences'+qs)]);
  S.cache.workforceTechs=techs;S.cache.crafts=crafts;S.cache.shifts=shifts;
  const total=techs.length,availableNow=techs.filter(t=>!t.current_absences?.length&&t.active).length,first=cap.weeks[0]||{capacity_hours:0},lowest=cap.weeks.reduce((m,w)=>Math.min(m,w.capacity_hours),Number.POSITIVE_INFINITY);
  const rows=techs.map(t=>[esc(t.full_name),status(t.craft_name||'Unassigned'),esc(t.site_name||'Shared'),`${fmt(t.weekly_hours)} h`,`${fmt(t.efficiency_pct)}%`,t.current_absences?.length?status('Absent'):status(t.active?'Available':'Inactive'),t.active_shifts?.map(x=>esc(x.shift_code)).join(', ')||'Fallback',roleIn('admin','maintenance_manager','planner')?`<button class="btn small" onclick="editTechnicianProfile(${t.user_id})">Profile</button> <button class="btn small" onclick="assignTechnicianShift(${t.user_id})">Shift</button>`:'—']);
  $('#content').innerHTML=`<div class="hero"><div><h1>Workforce Planning</h1><p>Crafts, technician profiles, shift calendars, absences and productive maintenance capacity.</p></div><div class="hero-actions">${roleIn('admin','maintenance_manager','planner','supervisor')?'<button class="btn primary" id="absence-new">+ Absence</button>':''}</div></div><div class="kpi-grid">${kpi('Technicians',total,'TC','Active workforce profiles')}${kpi('Available Today',availableNow,'AV','Not on approved absence',availableNow<total?'warn':'good')}${kpi('This Week Capacity',fmt(first.capacity_hours)+' h','CH','Shift/absence/efficiency adjusted')}${kpi('Lowest 8w Capacity',fmt(Number.isFinite(lowest)?lowest:0)+' h','LW','Planned capacity floor',lowest<first.capacity_hours?'warn':'good')}${kpi('Crafts',crafts.filter(x=>x.active).length,'CR','Maintenance disciplines')}</div><section class="panel"><div class="panel-head"><div><h3>Technician Roster</h3><p>Home site, craft, productive efficiency and active shifts.</p></div></div>${table(['Technician','Craft','Home Site','Base Week','Efficiency','Today','Shift','Action'],rows)}</section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>8-Week Capacity</h3><p>Available hours after shifts, approved absences and efficiency.</p></div></div>${table(['Week','Technicians','Capacity','Source','Craft Capacity'],cap.weeks.map(w=>[w.week_start,w.technicians,fmt(w.capacity_hours)+' h',esc(w.source),Object.entries(w.craft_capacity||{}).map(([k,v])=>`${esc(k)} ${fmt(v)}h`).join(' · ')]))}</section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Absence Calendar</h3><p>Approved and planned technician unavailability.</p></div></div>${absences.length?table(['Technician','Site','Type','Start','End','Hours/Day','Status'],absences.map(a=>[esc(a.full_name),esc(a.site_name||'—'),esc(a.absence_type),a.start_date,a.end_date,fmt(a.hours_per_day),status(a.status)])):empty('No absences recorded')}</section>`;
  if($('#absence-new'))$('#absence-new').onclick=()=>newWorkforceAbsence();
}
