async function renderApprovals(){
  const [list,delegations]=await Promise.all([api('/api/approvals?status='),api('/api/approval-delegations')]);S.cache.approvals=list;S.cache.delegations=delegations;
  const pending=list.filter(x=>x.status==='Pending'),approved=list.filter(x=>x.status==='Approved'),rejected=list.filter(x=>x.status==='Rejected');
  const activeDelegations=delegations.filter(x=>x.active&&x.end_at>=new Date().toISOString().slice(0,19));
  const rowsData=list.map(a=>{const actionable=a.status==='Pending'&&(roleIn('admin','maintenance_manager')||a.assigned_user_id===S.user.id||a.assigned_role===S.user.role||a.delegated_to_me);return [a.approval_no,esc(a.module),`<b>${esc(a.record_code)}</b>`,esc(a.title),esc(a.requested_by_name),esc(a.assigned_user_name||a.assigned_role||'Management')+(a.delegated_to_me?' <span class="badge">Delegated</span>':''),status(a.status),esc(a.requested_at),`${actionable?`<button class="btn small" onclick="decideApproval(${a.id},'approve')">Approve</button> <button class="btn small danger" onclick="decideApproval(${a.id},'reject')">Reject</button> `:''}<button class="btn small" onclick="approvalHistory(${a.id})">History</button>`]});
  const delegationRows=delegations.map(d=>[esc(d.delegator_name),esc(d.delegate_name),esc(d.module),esc(d.start_at),esc(d.end_at),status(d.active?'Active':'Inactive'),d.active&&d.delegator_user_id===S.user.id?`<button class="btn small danger" onclick="deactivateDelegation(${d.id})">Deactivate</button>`:'—']);
  $('#content').innerHTML=`<div class="hero"><div><h1>Approval Center</h1><p>Unified operational approvals with absence delegation and auditable decisions.</p></div><div class="hero-actions"><button class="btn primary" id="delegate-new">Delegate My Approvals</button></div></div><div class="kpi-grid">${kpi('Pending',pending.length,'AP','Awaiting decision',pending.length?'warn':'good')}${kpi('Approved',approved.length,'OK','Completed approvals','good')}${kpi('Rejected',rejected.length,'RJ','Returned for correction',rejected.length?'warn':'')}${kpi('Active Delegations',activeDelegations.length,'DG','Coverage during absence')}</div><section class="panel"><div class="panel-head"><div><h3>Approval Queue</h3><p>Assigned user/role, delegated authority, requester and workflow history</p></div></div>${table(['Approval','Module','Record','Title','Requested By','Assigned To','Status','Requested','Actions'],rowsData)}</section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Approval Delegations</h3><p>Temporary approval authority with start/end controls.</p></div></div>${delegationRows.length?table(['Delegator','Delegate','Module','Starts','Ends','Status','Action'],delegationRows):empty('No approval delegations')}</section>`;
  $('#delegate-new').onclick=()=>newApprovalDelegation();
}
function newApprovalDelegation(){const users=(S.ref.users||[]).filter(u=>u.id!==S.user.id);const dt=new Date(),end=new Date(Date.now()+7*86400000);const local=x=>{const o=new Date(x.getTime()-x.getTimezoneOffset()*60000);return o.toISOString().slice(0,16)};formModal('Delegate My Approvals',[field('Delegate','delegate_user_id','select','',{options:optionList(users,'id',x=>`${x.full_name} — ${x.role}`)}),field('Module','module','select','',{options:'<option value="*">All assigned approvals</option><option>Work Management</option><option>Procurement</option>'}),field('Start','start_at','datetime-local',local(dt)),field('End','end_at','datetime-local',local(end))],async d=>{await api('/api/approval-delegations',{method:'POST',body:JSON.stringify({delegate_user_id:Number(d.delegate_user_id),module:d.module,start_at:d.start_at,end_at:d.end_at})});await refreshNotifications()})}
