async function renderOperations(){const d=await api('/api/operations');const intel=d.intelligence||{};const outageRows=(d.open_outages||[]).map(o=>[o.outage_no,o.asset_no,esc(o.asset_name),esc(o.site_name||'—'),status(o.outage_type),esc(o.start_at),o.lost_capacity?`${fmt(o.lost_capacity)} ${esc(o.capacity_unit||'')}`:'—',`<button class="btn small" onclick="closeOutage(${o.id})">Close</button>`]);const alarmRows=(d.operational_alarms||[]).map(a=>[a.alarm_no,a.asset_no,esc(a.channel_name),status(a.severity),status(a.status),`${fmt(a.trigger_value)} ${esc(a.unit||'')}`,esc(a.last_seen_at),`<button class="btn small" onclick="go('telemetry')">Open</button>`]);$('#content').innerHTML=`<div class="hero"><div><h1>Utilities Operations</h1><p>Operational state, telemetry exceptions, outages and field response across electrical, water and infrastructure domains.</p></div><div class="hero-actions">${canWork()?'<button class="btn primary" id="outage-new">+ Record Outage</button>':''}<button class="btn" id="open-telemetry">Telemetry & Alarms</button></div></div><div class="kpi-grid">${d.domains.map(x=>kpi(x.domain,x.assets,'UT',`${x.attention} need attention`,x.attention?'warn':'good')).join('')}${kpi('Open Outages',(d.open_outages||[]).length,'OT','Assets currently unavailable',(d.open_outages||[]).length?'bad':'good')}${kpi('Active Alarms',intel.active_alarms||0,'AL',`${intel.critical_alarms||0} critical`,intel.active_alarms?'bad':'good')}${kpi('Telemetry Channels',intel.telemetry_channels||0,'TM',`${intel.stale_channels_24h||0} stale >24h`,intel.stale_channels_24h?'warn':'good')}</div><section class="panel"><div class="panel-head"><div><h3>Operational Alarms</h3><p>Threshold exceptions from telemetry channels</p></div></div>${alarmRows.length?table(['Alarm','Asset','Channel','Severity','Status','Value','Last Seen','Action'],alarmRows):empty('No active operational alarms')}</section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Open Outages</h3><p>Forced and planned unavailability with explicit timestamps</p></div></div>${outageRows.length?table(['Outage','Asset','Description','Site','Type','Start','Lost Capacity','Action'],outageRows):empty('No open outages')}</section><div class="panel-grid" style="margin-top:14px"><section class="panel"><div class="panel-head"><div><h3>Site Performance</h3><p>Assets and active maintenance</p></div></div>${table(['Site','Type','City','Assets','Open Work','Status'],d.sites.map(s=>[esc(s.name),esc(s.site_type),esc(s.city),s.assets,s.open_work,status(s.status)]))}</section><section class="panel"><div class="panel-head"><div><h3>Asset Condition Exceptions</h3><p>Condition and availability exceptions</p></div></div>${d.alerts.length?table(['Asset','Description','Site','Condition','Status'],d.alerts.map(a=>[a.asset_no,esc(a.name),esc(a.site_name||'—'),status(a.condition),status(a.status)])):empty('No condition exceptions')}</section></div>`;if(canWork())$('#outage-new').onclick=()=>newOutage();$('#open-telemetry').onclick=()=>go('telemetry')}

async function renderTelemetry(){const qs=S.siteId?`?site_id=${S.siteId}`:'';const [intel,channels,alarms]=await Promise.all([api('/api/operations/intelligence'+qs),api('/api/telemetry/channels'+qs),api('/api/alarms'+qs)]);S.cache.telemetryChannels=channels;S.cache.alarms=alarms;const active=alarms.filter(a=>['Open','Acknowledged'].includes(a.status));$('#content').innerHTML=`<div class="hero"><div><h1>Telemetry & Operational Alarms</h1><p>SCADA-style readings, threshold evaluation, alarm acknowledgement and maintenance conversion.</p></div><div class="hero-actions">${roleIn('admin','asset_manager','maintenance_manager','planner')?'<button class="btn" id="channel-new">+ Channel</button>':''}${canWork()?'<button class="btn primary" id="telemetry-ingest">Ingest Reading</button>':''}</div></div><div class="kpi-grid">${kpi('Channels',intel.telemetry_channels,'TM','Active telemetry points')}${kpi('Active Alarms',intel.active_alarms,'AL','Open / acknowledged',intel.active_alarms?'bad':'good')}${kpi('Critical',intel.critical_alarms,'!!','Immediate response required',intel.critical_alarms?'bad':'good')}${kpi('Stale >24h',intel.stale_channels_24h,'ST','No recent reading',intel.stale_channels_24h?'warn':'good')}</div><section class="panel"><div class="panel-head"><div><h3>Active Alarm Queue</h3><p>Acknowledge, convert to corrective work, and close after resolution</p></div></div>${active.length?table(['Alarm','Asset','Channel','Severity','Status','Value','Threshold','Last Seen','Work','Actions'],active.map(a=>[a.alarm_no,a.asset_no,esc(a.channel_name),status(a.severity),status(a.status),`${fmt(a.trigger_value)} ${esc(a.unit||'')}`,a.threshold_value==null?'—':fmt(a.threshold_value),esc(a.last_seen_at),a.wo_no||'—',alarmActions(a)])):empty('No active alarms')}</section><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Telemetry Channels</h3><p>Latest value, quality and configured thresholds</p></div></div>${table(['Channel','Asset','Metric','Latest','Quality','Last Reading','Warning','Critical'],channels.map(c=>[c.channel_code,c.asset_no,esc(c.name),c.last_value==null?'—':`${fmt(c.last_value)} ${esc(c.unit)}`,status(c.last_quality||'Unknown'),esc(c.last_reading_at||'—'),thresholdText(c,'warning'),thresholdText(c,'critical')]))}</section>`;if($('#channel-new'))$('#channel-new').onclick=()=>newTelemetryChannel();if($('#telemetry-ingest'))$('#telemetry-ingest').onclick=()=>ingestTelemetry()}
function thresholdText(c,level){const lo=c[`${level}_low`],hi=c[`${level}_high`];return [lo!=null?`≤ ${fmt(lo)}`:'',hi!=null?`≥ ${fmt(hi)}`:''].filter(Boolean).join(' / ')||'—'}
function alarmActions(a){const out=[];if(a.status==='Open')out.push(`<button class="btn small" onclick="ackAlarm(${a.id})">Acknowledge</button>`);if(!a.work_order_id&&roleIn('admin','asset_manager','maintenance_manager','planner','supervisor'))out.push(`<button class="btn primary small" onclick="alarmToWork(${a.id})">Create WO</button>`);if(roleIn('admin','asset_manager','maintenance_manager','planner','supervisor'))out.push(`<button class="btn small" onclick="closeAlarm(${a.id})">Close</button>`);return out.join(' ')||'—'}
async function newTelemetryChannel(){const assets=await api('/api/assets'+(S.siteId?`?site_id=${S.siteId}`:''));formModal('Create Telemetry Channel',[field('Channel Code','channel_code','text','',{required:false}),field('Asset','asset_id','select','',{options:optionList(assets,'id',x=>`${x.asset_no} — ${x.name}`)}),field('Name','name'),field('Metric Type','metric_type'),field('Unit','unit'),field('Source System','source_system','text','SCADA'),field('Warning Low','warning_low','number','',{required:false,step:'0.01'}),field('Critical Low','critical_low','number','',{required:false,step:'0.01'}),field('Warning High','warning_high','number','',{required:false,step:'0.01'}),field('Critical High','critical_high','number','',{required:false,step:'0.01'})],async d=>{for(const k of ['warning_low','critical_low','warning_high','critical_high'])d[k]=d[k]===''?null:Number(d[k]);d.asset_id=Number(d.asset_id);await api('/api/telemetry/channels',{method:'POST',body:JSON.stringify(d)});await renderTelemetry()})}
async function ingestTelemetry(){const channels=S.cache.telemetryChannels||await api('/api/telemetry/channels');formModal('Ingest Telemetry Reading',[field('Channel','channel_code','select','',{options:optionList(channels,'channel_code',x=>`${x.channel_code} — ${x.asset_no} · ${x.name}`,null,null)}),field('Value','value','number','',{step:'0.01'}),field('Quality','quality','select','Good',{options:'<option>Good</option><option>Uncertain</option><option>Bad</option>'}),field('Source','source','text','Manual',{required:false}),field('Captured At','captured_at','datetime-local','',{required:false})],async d=>{const r=await api('/api/telemetry/ingest',{method:'POST',body:JSON.stringify({readings:[{channel_code:d.channel_code,value:Number(d.value),quality:d.quality,source:d.source||null,captured_at:d.captured_at||null}]})});toast(`${r.accepted} reading accepted · ${r.alarms_opened} alarm opened · ${r.alarms_cleared} cleared`);await renderTelemetry()})}
window.ackAlarm=async id=>{try{await api(`/api/alarms/${id}/acknowledge`,{method:'POST'});toast('Alarm acknowledged');await renderTelemetry()}catch(e){toast(e.message)}}
window.closeAlarm=async id=>{try{await api(`/api/alarms/${id}/close`,{method:'POST'});toast('Alarm closed');await renderTelemetry()}catch(e){toast(e.message)}}
window.alarmToWork=async id=>{try{const r=await api(`/api/alarms/${id}/work-order`,{method:'POST',body:JSON.stringify({})});toast(`${r.wo_no} created`);await renderTelemetry()}catch(e){toast(e.message)}}

async function newOutage(){const assets=await api('/api/assets'+(S.siteId?`?site_id=${S.siteId}`:''));const work=await api('/api/work-orders'+(S.siteId?`?site_id=${S.siteId}`:''));formModal('Record Asset Outage',[field('Asset','asset_id','select','',{options:optionList(assets,'id',x=>`${x.asset_no} — ${x.name}`)}),field('Related Work Order','work_order_id','select','',{required:false,options:optionList(work,'id',x=>`${x.wo_no} — ${x.title}`,null,'None')}),field('Outage Type','outage_type','select','Forced',{options:'<option>Forced</option><option>Planned</option>'}),field('Cause Code','cause_code','text','',{required:false}),field('Start Time','start_at','datetime-local','',{required:false}),field('Lost Capacity','lost_capacity','number','0',{step:'0.1'}),field('Capacity Unit','capacity_unit','text','',{required:false}),field('Impact','impact','textarea','',{full:true,required:false})],async d=>{await api('/api/outages',{method:'POST',body:JSON.stringify({asset_id:Number(d.asset_id),work_order_id:d.work_order_id?Number(d.work_order_id):null,outage_type:d.outage_type,cause_code:d.cause_code,impact:d.impact,lost_capacity:Number(d.lost_capacity||0),capacity_unit:d.capacity_unit,start_at:d.start_at||null})});await renderOperations()})}
window.closeOutage=async id=>{if(!confirm('Close this outage and restore the asset to Operating when no other outage is open?'))return;try{await api(`/api/outages/${id}/close`,{method:'POST',body:JSON.stringify({})});toast('Outage closed');await renderOperations()}catch(e){toast(e.message)}}

async function renderMap(){const sites=await api('/api/map');S.cache.map=sites;const lats=sites.map(x=>x.latitude),lons=sites.map(x=>x.longitude),minLat=Math.min(...lats),maxLat=Math.max(...lats),minLon=Math.min(...lons),maxLon=Math.max(...lons);const pos=s=>({x:10+(s.longitude-minLon)/Math.max(maxLon-minLon,.01)*80,y:10+(maxLat-s.latitude)/Math.max(maxLat-minLat,.01)*80});$('#content').innerHTML=`<div class="hero"><div><h1>GIS / Location Management</h1><p>Region → City → Site → Building → Floor → Room → Asset.</p></div></div><div class="map-layout"><div class="geo-map">${sites.map(s=>{const p=pos(s);return `<button class="map-pin" data-site="${s.id}" style="left:${p.x}%;top:${p.y}%"><div class="pin-dot"></div><div class="pin-label">${esc(s.site_code)} · ${s.assets} assets</div></button>`}).join('')}</div><aside class="map-side" id="map-side">${empty('Select a site pin to inspect assets, work and field coverage.')}</aside></div>`;$$('.map-pin').forEach(p=>p.onclick=()=>showMapSite(Number(p.dataset.site)))}
function showMapSite(id){const s=S.cache.map.find(x=>x.id===id);$('#map-side').innerHTML=`<div class="eyebrow dark">${esc(s.site_code)}</div><h3>${esc(s.name)}</h3><p>${esc(s.city)} · ${esc(s.site_type)}<br>Coordinates: ${s.latitude.toFixed(4)}, ${s.longitude.toFixed(4)}</p><div class="detail-grid" style="grid-template-columns:1fr 1fr"><div class="detail-box"><span>Assets</span><strong>${s.assets}</strong></div><div class="detail-box"><span>Open Work</span><strong>${s.open_work}</strong></div></div><div class="subsection"><h3>Assets</h3><div class="map-assets">${s.asset_list.length?s.asset_list.map(a=>`<div class="map-asset"><strong>${esc(a.asset_no)} · ${esc(a.name)}</strong><span>${esc(a.condition)} · ${esc(a.status)}</span></div>`).join(''):empty('No assets')}</div></div><div class="subsection"><h3>Field Coverage</h3><p>${s.technicians.map(t=>esc(t.full_name)).join(', ')||'No active technicians'}</p></div>`}

async function renderDispatch(){const board=await api('/api/dispatch/board'+(S.siteId?`?site_id=${S.siteId}`:''));const all=await api('/api/dispatch');const active=all.filter(d=>['Dispatched','Accepted','En Route','On Site'].includes(d.status));$('#content').innerHTML=`<div class="hero"><div><h1>Technician Dispatch</h1><p>Coordinate approved work, field travel, arrival and technician availability.</p></div></div><div class="kpi-grid">${kpi('Technicians',board.technicians.length,'TC','Dispatchable workforce')}${kpi('Available',board.technicians.filter(t=>t.availability==='Available').length,'AV','Ready for assignment','good')}${kpi('Active Dispatches',active.length,'DP','Dispatched / travelling / on site',active.length?'warn':'good')}${kpi('Ready Work',board.work_queue.length,'WO','Approved or assigned work')}</div><div class="panel-grid"><section class="panel"><div class="panel-head"><div><h3>Technician Board</h3><p>One active dispatch per technician</p></div></div>${table(['Technician','Craft','Site','Availability','Current Dispatch','Work'],board.technicians.map(t=>[esc(t.full_name),esc(t.craft_code||'—'),esc(t.site_name||'—'),status(t.availability),t.dispatch?status(t.dispatch.status):'—',t.dispatch?`${t.dispatch.wo_no} · ${esc(t.dispatch.title)}`:'—']))}</section><section class="panel"><div class="panel-head"><div><h3>Ready Work Queue</h3><p>Approved/assigned work waiting for coordinated execution</p></div></div>${board.work_queue.length?table(['WO','Title','Priority','Status','Technician','Action'],board.work_queue.map(w=>[w.wo_no,esc(w.title),status(w.priority),status(w.status),esc(w.assigned_to_name||'Unassigned'),roleIn('admin','maintenance_manager','planner','supervisor')?`<button class="btn small" onclick="dispatchWork(${w.id})">Dispatch</button>`:'—'])):empty('No ready work')}</section></div><section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Dispatch Activity</h3><p>Acceptance, travel, arrival and completion status</p></div></div>${all.length?table(['Dispatch','Work','Technician','Site','Priority','Status','ETA','Dispatched','Action'],all.slice(0,30).map(d=>[d.dispatch_no,d.wo_no,esc(d.technician_name),esc(d.site_name||'—'),status(d.priority),status(d.status),d.eta_minutes==null?'—':`${d.eta_minutes} min`,esc(d.dispatched_at),dispatchActionButtons(d)])):empty('No dispatch records')}</section>`}
function dispatchActionButtons(d){if(S.user.role==='technician'&&Number(d.technician_user_id)!==Number(S.user.id))return '—';const elevated=roleIn('admin','maintenance_manager','planner','supervisor');const a=[];if(d.status==='Dispatched')a.push(`<button class="btn small" onclick="dispatchTransition(${d.id},'accept')">Accept</button>`);if(d.status==='Accepted')a.push(`<button class="btn small" onclick="dispatchTransition(${d.id},'enroute')">En Route</button>`);if(d.status==='En Route')a.push(`<button class="btn primary small" onclick="dispatchTransition(${d.id},'arrive')">Arrive</button>`);if(d.status==='On Site')a.push(`<button class="btn small" onclick="dispatchTransition(${d.id},'complete')">Finish Dispatch</button>`);if(elevated&&['Dispatched','Accepted','En Route','On Site'].includes(d.status))a.push(`<button class="btn danger small" onclick="dispatchTransition(${d.id},'cancel')">Cancel</button>`);return a.join(' ')||'—'}
window.dispatchWork=async woId=>{const techs=S.ref.users.filter(u=>u.role==='technician');formModal('Dispatch Technician',[field('Technician','technician_user_id','select','',{options:optionList(techs,'id',x=>`${x.full_name} — ${x.department||'Technician'}`)}),field('ETA (minutes)','eta_minutes','number','30',{required:false}),field('Dispatch Notes','notes','textarea','',{full:true,required:false})],async d=>{await api(`/api/work-orders/${woId}/dispatch`,{method:'POST',body:JSON.stringify({technician_user_id:Number(d.technician_user_id),eta_minutes:d.eta_minutes?Number(d.eta_minutes):null,notes:d.notes})});toast('Technician dispatched');if(S.view==='dispatch')await renderDispatch();else await workDetail(woId)})}
window.dispatchTransition=async(id,action)=>{try{await api(`/api/dispatch/${id}/transition`,{method:'POST',body:JSON.stringify({action})});toast('Dispatch updated');if(S.view==='dispatch')await renderDispatch();else if(S.view==='field')await renderField()}catch(e){toast(e.message)}}

async function renderField(){const d=await api('/api/field/my-work');S.cache.field=d;const tabs=[['assigned','Assigned'],['today','Today'],['in_progress','In Progress'],['overdue','Overdue'],['completed','Completed']];const list=d[S.fieldTab]||[];$('#content').innerHTML=`<div class="hero"><div><h1>My Work</h1><p>Tablet and mobile technician workspace for ${esc(S.user.full_name)}.</p></div><div class="hero-actions"><button class="btn" id="field-dispatch">Dispatch Status</button></div></div><div class="field-tabs">${tabs.map(t=>`<button class="tab-btn ${S.fieldTab===t[0]?'active':''}" data-ftab="${t[0]}">${t[1]} (${d[t[0]].length})</button>`).join('')}</div><div>${list.length?list.map(w=>`<article class="mobile-work-card"><div class="wo-top"><div><div class="eyebrow dark">${esc(w.wo_no)} · ${esc(w.asset_no||'NO ASSET')}</div><h3>${esc(w.title)}</h3><p>${esc(w.location_name||'—')} · Due ${esc(w.target_finish||'—')}</p></div>${status(w.priority)}</div><div class="action-row"><button class="btn small" onclick="workDetail(${w.id})">Open Job</button>${w.status==='Assigned'?`<button class="btn primary small" onclick="fieldAction(${w.id},'start')">Start Work</button>`:''}${w.status==='In Progress'?`<button class="btn small" onclick="fieldAction(${w.id},'pause')">Pause</button><button class="btn primary small" onclick="fieldAction(${w.id},'complete')">Complete</button>`:''}${canInv()?`<button class="btn small" onclick="fieldPart(${w.id})">Consume Part</button>`:''}${canWork()?`<button class="btn small" onclick="fieldRead(${w.id})">Reading / Condition</button><button class="btn small" onclick="fieldNote(${w.id})">Note</button>`:''}</div></article>`).join(''):empty(S.user.role==='technician'?'No work in this category.':'Field Service shows work assigned to the signed-in user. Sign in as tech1 / Tech@2026 for the technician demonstration.')}</div>`;$$('[data-ftab]').forEach(b=>b.onclick=()=>{S.fieldTab=b.dataset.ftab;renderField()});if($('#field-dispatch'))$('#field-dispatch').onclick=()=>go('dispatch')}
window.fieldAction=async(id,action)=>{try{const notes=action==='complete'?(prompt('Completion notes:','Completed and tested.')||'Completed'):'';const signature=action==='complete'?(prompt('Technician signature / name:',S.user.full_name)||''):'';await api(`/api/work-orders/${id}/transition`,{method:'POST',body:JSON.stringify({action,notes,signature})});toast('Job updated');await renderField()}catch(e){toast(e.message)}}
window.fieldPart=async id=>{const w=await api('/api/work-orders/'+id);await addPart(w)}
window.fieldRead=async id=>{const w=await api('/api/work-orders/'+id);fieldReading(w)}
window.fieldNote=async id=>{const w=await api('/api/work-orders/'+id);addNote(w)}

async function renderInspections(){const list=await api('/api/inspections');S.cache.inspections=list;$('#content').innerHTML=`<div class="hero"><div><h1>Inspection Management</h1><p>Digital inspection forms with automatic corrective work creation on failure.</p></div><div class="hero-actions">${canWork()?'<button class="btn primary" id="inspection-new">+ Inspection</button>':''}</div></div><section class="panel">${table(['Inspection','Template','Asset','Inspector','Status','Result','Date','Corrective WO','Action'],list.map(i=>[i.inspection_no,esc(i.template_name),esc(i.asset_no||'—'),esc(i.inspector_name||'—'),status(i.status),status(i.result||'Draft'),esc(i.inspected_at||'—'),esc(i.corrective_wo_no||'—'),`<button class="btn small" onclick="inspectionDetail(${i.id})">Open</button>`]))}</section>`;if(canWork())$('#inspection-new').onclick=()=>newInspection()}
async function newInspection(){if(!S.cache.assets)S.cache.assets=await api('/api/assets');formModal('Create Inspection',[field('Template','template_name','select','',{options:'<option>Transformer Inspection</option><option>Electrical Safety Inspection</option><option>Pump Condition Inspection</option><option>Facility Inspection</option>'}),field('Asset','asset_id','select','',{required:false,options:optionList(S.cache.assets,'id',x=>`${x.asset_no} — ${x.name}`,null,'No asset')}),field('Custom Items (comma separated)','items_text','textarea','Oil Level, Oil Leakage, Temperature, Voltage, Current, Noise, Grounding, Physical Damage',{full:true,required:false})],async d=>{await api('/api/inspections',{method:'POST',body:JSON.stringify({template_name:d.template_name,asset_id:d.asset_id?Number(d.asset_id):null,items:d.items_text?d.items_text.split(',').map(x=>x.trim()).filter(Boolean):[]})})})}
window.inspectionDetail=async id=>{const i=await api('/api/inspections/'+id);if(i.status==='Completed'){openModal(`${i.inspection_no} — ${i.template_name}`,`<div class="detail-grid"><div class="detail-box"><span>Status</span><strong>${esc(i.status)}</strong></div><div class="detail-box"><span>Result</span><strong>${esc(i.result)}</strong></div><div class="detail-box"><span>Inspected</span><strong>${esc(i.inspected_at||'—')}</strong></div><div class="detail-box"><span>Remarks</span><strong>${esc(i.remarks||'—')}</strong></div></div>${table(['Item','Response','Reading','Remarks'],i.items.map(x=>[esc(x.item_name),status(x.response||'—'),esc(x.reading||'—'),esc(x.remarks||'—')]))}`);return}openModal(`${i.inspection_no} — ${i.template_name}`,`<form id="inspection-form"><div class="checklist">${i.items.map(x=>`<div class="check-row"><strong>${esc(x.item_name)}</strong><select data-response="${x.id}"><option>Pass</option><option>Fail</option><option>N/A</option></select><input data-reading="${x.id}" placeholder="Reading / notes"></div>`).join('')}</div><label class="field" style="margin-top:15px">Overall Remarks<textarea id="inspection-remarks"></textarea></label><label style="display:flex;gap:8px;align-items:center;font-size:11px;margin-top:10px"><input type="checkbox" id="inspection-auto" checked> Automatically create corrective work order if any item fails</label><div class="form-actions" style="margin-top:15px"><button class="btn primary">Submit Inspection</button></div></form>`);$('#inspection-form').onsubmit=async e=>{e.preventDefault();const responses=i.items.map(x=>({id:x.id,response:document.querySelector(`[data-response="${x.id}"]`).value,reading:document.querySelector(`[data-reading="${x.id}"]`).value,remarks:''}));try{const r=await api(`/api/inspections/${id}/submit`,{method:'POST',body:JSON.stringify({responses,remarks:$('#inspection-remarks').value,create_corrective_on_fail:$('#inspection-auto').checked})});toast(r.result==='Fail'?(r.corrective_work_order_id?'Inspection failed — corrective WO generated':'Inspection failed'):'Inspection passed');closeModal();await renderInspections();await refreshNotifications()}catch(err){toast(err.message)}}}

async function renderHSE(){const list=await api('/api/hse');S.cache.hse=list;const open=list.filter(x=>x.status!=='Closed').length,high=list.filter(x=>x.risk_score>=12).length;$('#content').innerHTML=`<div class="hero"><div><h1>Safety & HSE</h1><p>Incidents, hazards, near misses, risk and corrective actions.</p></div><div class="hero-actions">${canHSE()?'<button class="btn primary" id="hse-new">+ HSE Record</button>':''}</div></div><div class="kpi-grid">${kpi('HSE Records',list.length,'HS','Safety register')}${kpi('Open Actions',open,'OA','Requires follow-up',open?'warn':'good')}${kpi('High Risk',high,'HR','Risk score ≥ 12',high?'warn':'good')}${kpi('Closed',list.filter(x=>x.status==='Closed').length,'CL','Resolved records')}</div><section class="panel">${table(['Incident','Type','Title','Site','Severity','Probability','Risk','Status','Occurred','Action'],list.map(h=>[h.incident_no,esc(h.incident_type),esc(h.title),esc(h.site_name||'—'),h.severity,h.probability,`<span class="risk ${h.risk_score>=12?'high':h.risk_score>=5?'med':'low'}">${h.risk_score}</span>`,status(h.status),esc(h.occurred_at),canHSE()?`<button class="btn small" onclick="manageHSE(${h.id})">Manage</button>`:'—']))}</section>`;if(canHSE())$('#hse-new').onclick=()=>newHSE()}
