async function renderProjects(){const list=await api('/api/projects');S.cache.projects=list;const budget=list.reduce((s,x)=>s+x.budget,0),actual=list.reduce((s,x)=>s+x.actual_cost,0);$('#content').innerHTML=`<div class="hero"><div><h1>Projects</h1><p>Capital and reliability projects connected to sites, assets and work.</p></div><div class="hero-actions">${canProject()?'<button class="btn primary" id="project-new">+ Project</button>':''}</div></div><div class="kpi-grid">${kpi('Active Projects',list.filter(x=>x.status==='Active').length,'PJ','Portfolio')}${kpi('Portfolio Budget',fmtMoney(budget),'BG','Approved budget')}${kpi('Actual Cost',fmtMoney(actual),'AC',`${budget?Math.round(actual/budget*100):0}% consumed`)}${kpi('Average Progress',fmt(list.reduce((s,x)=>s+x.progress,0)/Math.max(list.length,1))+'%','PR','Delivery progress')}</div><div class="card-grid">${list.map(p=>`<article class="entity-card"><div class="detail-head"><div><h3>${esc(p.project_no)} · ${esc(p.name)}</h3><p>${esc(p.site_name||'—')} · ${esc(p.manager_name||'—')}</p></div>${status(p.status)}</div><div class="meta-grid"><div class="meta"><span>Budget</span><strong>${fmtMoney(p.budget)}</strong></div><div class="meta"><span>Actual</span><strong>${fmtMoney(p.actual_cost)}</strong></div><div class="meta"><span>Start</span><strong>${esc(p.start_date||'—')}</strong></div><div class="meta"><span>Finish</span><strong>${esc(p.finish_date||'—')}</strong></div></div><div class="progress"><span style="width:${p.progress}%"></span></div><p>${fmt(p.progress)}% complete · ${p.tasks.length} tracked tasks</p><div class="task-list">${p.tasks.map(t=>`<button class="task-row" ${canProject()?`onclick="editProjectTask(${p.id},${t.id})"`:''}><span>${esc(t.task_name)}</span><b>${fmt(t.progress)}%</b><small>${esc(t.status)}</small></button>`).join('')||'<span class="section-sub">No tasks yet.</span>'}</div>${canProject()?`<button class="btn small" onclick="addProjectTask(${p.id})">+ Task</button>`:''}</article>`).join('')}</div>`;if(canProject())$('#project-new').onclick=()=>newProject()}
window.addProjectTask=projectId=>formModal('Add Project Task',[field('Task','task_name'),field('Owner','owner_id','select','',{required:false,options:optionList(S.ref.users,'id','full_name',null,'Unassigned')}),field('Due Date','due_date','date','',{required:false}),field('Status','status','select','',{options:'<option>Open</option><option>In Progress</option><option>Blocked</option><option>Completed</option>'}),field('Progress %','progress','number','0')],async d=>{d.owner_id=d.owner_id?Number(d.owner_id):null;d.progress=Number(d.progress);await api(`/api/projects/${projectId}/tasks`,{method:'POST',body:JSON.stringify(d)})})
