  const eventRows=outbox.map(e=>[e.event_no,esc(e.event_type),esc(e.aggregate_type),esc(e.aggregate_id),(e.status==='Failed'&&e.max_attempts&&e.attempts>=e.max_attempts?status('Exhausted'):status(e.status)),e.attempts,esc(e.created_at),e.status==='Failed'&&roleIn('admin','maintenance_manager')?`<button class="btn small" onclick="retryOutbox(${e.id})">Retry</button>`:'—']);
