window.editSlaPolicy=id=>{const p=S.cache.slaPolicies?.find(x=>x.id===id);const load=async()=>{const pol=p||((S.cache.slaPolicies=await api('/api/sla/policies')).find(x=>x.id===id));formModal(`Edit ${pol.policy_code}`,[field('Response Minutes','response_minutes','number',pol.response_minutes),field('Resolution Minutes','resolution_minutes','number',pol.resolution_minutes),field('Active','active','select','',{options:`<option value="true" ${pol.active?'selected':''}>Active</option><option value="false" ${!pol.active?'selected':''}>Inactive</option>`})],async d=>{await api(`/api/sla/policies/${id}`,{method:'PATCH',body:JSON.stringify({response_minutes:Number(d.response_minutes),resolution_minutes:Number(d.resolution_minutes),active:d.active==='true'})});S.cache.slaPolicies=null;await renderAutomation()})};load()}
window.retryOutbox=async id=>{try{await api(`/api/events/outbox/${id}/retry`,{method:'POST'});toast('Event queued for retry');await renderAutomation()}catch(e){toast(e.message)}}
window.editRetention=id=>{const r=(S.cache.retention||[]).find(x=>x.id===id);if(!r)return;formModal(`Retention — ${r.data_class}`,[field('Retention Days','retention_days','number',r.retention_days),field('Active','active','select','',{options:`<option value="true" ${r.active?'selected':''}>Active</option><option value="false" ${!r.active?'selected':''}>Inactive</option>`})],async d=>{await api(`/api/governance/retention/${id}`,{method:'PATCH',body:JSON.stringify({retention_days:Number(d.retention_days),active:d.active==='true'})});await renderAutomation()})}

async function renderAdmin(){if(!roleIn('admin','maintenance_manager','executive')){$('#content').innerHTML=empty('Administration is restricted by role-based access control.');return}const [audit,integrity]=await Promise.all([api('/api/audit'),api('/api/audit/integrity')]);let users=[];if(roleIn('admin'))users=await api('/api/admin/users');S.cache.adminUsers=users;$('#content').innerHTML=`<div class="hero"><div><h1>Administration</h1><p>Users, roles, access control and tamper-evident activity traceability.</p></div><div class="hero-actions">${status(integrity.valid?'Audit Verified':'Audit FAILED')}${roleIn('admin')?'<button class="btn primary" id="user-new">+ User</button>':''}</div></div>${roleIn('admin')?`<section class="panel"><div class="panel-head"><div><h3>Users & RBAC</h3><p>Enterprise roles and access</p></div></div>${table(['User','Name','Role','Department','Email','Status','Action'],users.map(u=>[u.username,esc(u.full_name),status(u.role_name),esc(u.department||'—'),esc(u.email||'—'),status(u.active?'Active':'Inactive'),u.id===S.user.id?'Current user':`<button class="btn small" onclick="toggleUser(${u.id},${u.active?0:1})">${u.active?'Deactivate':'Activate'}</button>`]))}</section>`:''}<section class="panel" style="margin-top:14px"><div class="panel-head"><div><h3>Audit Trail</h3><p>User, time, action, module, record, old and new value</p></div></div>${table(['Time','User','Action','Module','Record','Old Value','New Value','Hash'],audit.map(x=>[esc(x.created_at),esc(x.full_name),status(x.action),esc(x.module),esc(x.record_id),`<span title="${esc(x.old_value)}">${esc((x.old_value||'—').slice(0,35))}</span>`,`<span title="${esc(x.new_value)}">${esc((x.new_value||'—').slice(0,35))}</span>`,`<span title="${esc(x.audit_hash||'')}">${esc((x.audit_hash||'—').slice(0,12))}${x.audit_hash?'…':''}</span>`]))}</section>`;if(roleIn('admin'))$('#user-new').onclick=()=>newUser()}
window.toggleUser=async(id,active)=>{try{await api(`/api/admin/users/${id}/status`,{method:'PATCH',body:JSON.stringify({active:!!active})});toast(active?'User activated':'User deactivated');await renderAdmin()}catch(e){toast(e.message)}}
async function newUser(){const roles=await api('/api/admin/roles');formModal('Create User',[field('Username','username'),field('Password','password','password'),field('Full Name','full_name'),field('Email','email','email','',{required:false}),field('Role','role_code','select','',{options:optionList(roles,'code','name',null,null)}),field('Department','department','text','',{required:false}),field('Phone','phone','text','',{required:false})],async d=>{await api('/api/admin/users',{method:'POST',body:JSON.stringify(d)})})}

